//! A Rust API with public reexports, traits, and checked examples.
//!
//! Start with [`Counter`] or [`Mode::Fast`].
//!
//! ```
//! use rust_demo::Counter;
//! let counter = Counter::new(3_u32);
//! assert_eq!(counter.value, 3);
//! ```

mod model;
pub use model::Counter;

/// Operations shared by named values.
pub trait Named {
    /// The native value type.
    type Value;
    /// The default label.
    const LABEL: &'static str;
    /// Return the native value.
    fn read(&self) -> Self::Value;
    /// Return [`Self::LABEL`].
    fn label(&self) -> &'static str {
        Self::LABEL
    }
    #[doc(hidden)]
    fn hidden(&self) {}
}

/// Select [`Self::Fast`] or a custom shape.
#[non_exhaustive]
pub enum Mode {
    /// A unit variant.
    Fast,
    /// A tuple variant.
    Count(u32),
    /// A struct variant with a documented field.
    Custom {
        /// The requested width.
        width: f64,
    },
}

#[doc = include_str!("../included.md")]
pub fn included() {}

/// An alias for the reexported counter.
pub type DefaultCounter = Counter<u32>;

/// A stable public constant.
pub const DEFAULT_COUNT: u32 = 3;

/// An optional API selected by the `extra` feature.
#[cfg(feature = "extra")]
pub fn extra() {}

#[doc(hidden)]
pub struct Invisible;

macro_rules! generated_api {
    () => {
        /// A public API generated by a declarative macro.
        pub fn generated() -> u32 {
            7
        }
    };
}
generated_api!();

